sn_aia_tool.script:
(function(inputs) {
  var result = { status: 'success', catalog: [], totalMonitored: 0 };
  try {
    var monitoredPlugins = [
      { id: 'com.snc.now_assist_ai_agents', name: 'Now Assist AI Agents', category: 'ai', critical: true },
      { id: 'com.snc.ai_control_tower', name: 'AI Control Tower', category: 'ai', critical: true },
      { id: 'com.snc.now_assist_itsm', name: 'Now Assist for ITSM', category: 'itsm', critical: true },
      { id: 'com.snc.now_assist_hrsd', name: 'Now Assist for HRSD', category: 'hrsd', critical: false },
      { id: 'com.snc.now_assist_csm', name: 'Now Assist for CSM', category: 'csm', critical: false },
      { id: 'com.snc.predictive_intelligence', name: 'Predictive Intelligence', category: 'ai', critical: true },
      { id: 'com.snc.virtual_agent', name: 'Virtual Agent', category: 'ai', critical: false },
      { id: 'com.snc.integration_hub', name: 'Integration Hub', category: 'integration', critical: false }
    ];

    var filter = (inputs.category_filter || 'all').toLowerCase();
    if (filter !== 'all' && filter !== '') {
      result.catalog = monitoredPlugins.filter(function(p) { return p.category === filter; });
    } else {
      result.catalog = monitoredPlugins;
    }
    result.totalMonitored = result.catalog.length;
  } catch (e) {
    result.status = 'error';
    result.message = 'Failed to load catalog: ' + e.message;
  }
  return result;
})(inputs);
